import{_ as i,C as d,o as a,c as s,a3 as A,b as n,w as e,a as t,E as o,a4 as B,j as l}from"./chunks/framework.CWYzGJW1.js";const f=JSON.parse('{"title":"K1 模型如何運作","description":"模型是一大批訓練出來的數字 (權重), 推論伺服器 (inference server) 是把這批數字載入記憶體, 並讓其他程式可以呼叫的服務.","frontmatter":{"description":"模型是一大批訓練出來的數字 (權重), 推論伺服器 (inference server) 是把這批數字載入記憶體, 並讓其他程式可以呼叫的服務."},"headers":[],"relativePath":"know/k1-basics.md","filePath":"know/k1-basics.md","lastUpdated":1793064110000}'),p={name:"know/k1-basics.md"};function h(m,E,g,b,k,C){const r=d("Mermaid");return a(),s("div",null,[E[9]||(E[9]=A('<h1 id="k1-模型如何運作" tabindex="-1">K1 模型如何運作 <a class="header-anchor" href="#k1-模型如何運作" aria-label="Permalink to &quot;K1 模型如何運作&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li></ul></div><p><strong>結論</strong>: 模型是一大批訓練出來的數字 (權重), 推論伺服器 (inference server) 是把這批數字載入記憶體, 並讓其他程式可以呼叫的服務. 輸入的文字會先被切成小片段 (token), 模型逐段算出下一個片段, 再接成完整回答. 「問自己的文件」另外需要一個嵌入模型 (embedding model), 負責依意思找出相關段落. 地端模型和雲端模型一樣帶著訓練時學到的知識, 也可能記住部分訓練資料; 兩者的差別在「在哪裡跑, 輸入交給誰」, 不在「知道什麼」. 地端不必然優於雲端, 取捨見 K1.8 節與<a href="/lanai-handbook/decide/summary">一頁決策摘要</a>.</p><div class="tip custom-block"><p class="custom-block-title">本章常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>模型 (model)</td><td>讀過大量文字, 能接著把話寫下去的程式</td></tr><tr><td>權重 (weights) 與參數 (parameter)</td><td>模型學到的內容, 以大量數字存成檔案; 每一個數字就是一個參數</td></tr><tr><td>token</td><td>模型讀文字時切出來的小片段</td></tr><tr><td>上下文長度 (context length)</td><td>模型一次能處理多少 token, 包含問題和回答</td></tr><tr><td>推論 (inference)</td><td>拿現成的模型產生回答, 不重新訓練</td></tr><tr><td>GPU 與顯示記憶體</td><td>GPU 是擅長大量同時運算的晶片, 也就是顯示卡的核心; 顯示記憶體是顯示卡專用的記憶體</td></tr><tr><td>API</td><td>程式之間約定好的請求格式, 讓一個程式可以請另一個程式做事</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="k1-1-模型是一組數字-參數越多檔案越大" tabindex="-1">K1.1 模型是一組數字, 參數越多檔案越大 <a class="header-anchor" href="#k1-1-模型是一組數字-參數越多檔案越大" aria-label="Permalink to &quot;K1.1 模型是一組數字, 參數越多檔案越大&quot;">​</a></h2><p>模型不是一本能翻閱的書, 也不是一份資料庫, 而是一大批數字. 這些數字在訓練時一點一點調整出來, 目標是讓模型更會猜「下一段文字是什麼」. 可以想成一台有 80 億個旋鈕的調音台: 旋鈕的位置決定輸出的聲音, 但光看旋鈕位置, 看不出這台機器「記得什麼」.</p><p>模型 (model) 在本手冊指大型語言模型: 輸入一段文字, 輸出下一段文字的程式. 它的「能力」存放在權重 (weights) 裡. 權重是訓練過程調整出來的大量數字, 每一個數字稱為一個參數 (parameter); 「8B」代表約 80 億個參數 (B 是 billion, 十億).</p><p>參數量直接決定權重檔的大小. 電腦存一個數字時, 可以選擇存得精細或粗略, 稱為精度. 以 16 位元精度存放時, 每個參數占 2 位元組 (byte, 電腦儲存容量的基本單位), 因此 80 億參數約 16GB (80 億乘以 2 位元組). 同一個數字存得粗一點, 檔案就會變小, 這個做法稱為量化 (quantization), 估算方法見 <a href="/lanai-handbook/know/k2-quantization">K2</a>. 參數量越大, 能力通常越好, 但需要的記憶體與運算也越多 (信心: 高, 屬一般經驗).</p><p>下圖是權重檔大小的算法:</p>',9)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-105",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%A8%93%E7%B7%B4%3A%20%E4%B8%80%E9%BB%9E%E4%B8%80%E9%BB%9E%E8%AA%BF%E6%95%B4%E6%95%B8%E5%AD%97%22%5D%20--%3E%20B%5B%22%E6%AC%8A%E9%87%8D%20(weights)%3Cbr%2F%3E%E6%AF%8F%E5%80%8B%E6%95%B8%E5%AD%97%E6%98%AF%E4%B8%80%E5%80%8B%E5%8F%83%E6%95%B8%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8F%83%E6%95%B8%E9%87%8F%3Cbr%2F%3E%E4%BE%8B%3A%208B%20%3D%20%E7%B4%84%2080%20%E5%84%84%E5%80%8B%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%B9%98%E4%B8%8A%E6%AF%8F%E5%80%8B%E5%8F%83%E6%95%B8%E7%9A%84%E4%BD%8D%E5%85%83%E7%B5%84%E6%95%B8%3Cbr%2F%3E16%20%E4%BD%8D%E5%85%83%E7%B2%BE%E5%BA%A6%20%3D%202%20%E4%BD%8D%E5%85%83%E7%B5%84%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%AC%8A%E9%87%8D%E6%AA%94%E5%A4%A7%E5%B0%8F%3Cbr%2F%3E80%20%E5%84%84%20x%202%20%E4%BD%8D%E5%85%83%E7%B5%84%20%E2%89%88%2016GB%22%5D%0A%20%20D%20-.%20%22%E5%AD%98%E5%BE%97%E7%B2%97%E4%B8%80%E9%BB%9E%20(%E9%87%8F%E5%8C%96%2C%20%E8%A6%8B%20K2)%22%20.-%3E%20F%5B%22%E6%AA%94%E6%A1%88%E8%AE%8A%E5%B0%8F%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[10]||(E[10]=A('<p>權重本身不是可讀的資料庫, 無法像查表一樣找出「某一筆知識存在哪裡」(信心: 中, 屬一般理解). 這點會影響 K1.7 節的隱私判斷.</p><p><strong>在架構圖上的位置</strong>: VM 推論區載入的模型檔, 以及 NAS 上的 NFS 模型存放區 (見 <a href="/lanai-handbook/build/m3-model-intake">M3</a>).</p><h2 id="k1-2-token-與上下文長度-模型一次看得到多少字" tabindex="-1">K1.2 token 與上下文長度: 模型一次看得到多少字 <a class="header-anchor" href="#k1-2-token-與上下文長度-模型一次看得到多少字" aria-label="Permalink to &quot;K1.2 token 與上下文長度: 模型一次看得到多少字&quot;">​</a></h2><p>模型不是一個字一個字讀文章, 而是先把文章切成一塊一塊的小片段, 每一塊稱為 token, 就像把句子拆成拼字積木. 模型一次能放在「桌面上」處理的積木數量有上限, 這個上限稱為上下文長度. 問題, 貼進去的資料和模型寫出的回答, 都算在同一張桌面上; 桌面越大, 需要的記憶體越多, 回應通常也越慢.</p><p>token 是模型處理文字的最小單位. 模型不直接讀「字」, 而是讀一串 token 編號: 一個 token 可能是一個英文單字, 單字的一部分, 一個標點, 或一至數個中文字, 切法依模型而定.</p><p>上下文長度 (context length) 是模型一次能處理的 token 上限, 包含輸入與已產生的輸出. Ollama 是在本機載入模型並提供 API 的推論伺服器 (見 <a href="/lanai-handbook/build/m1-inference">M1</a>), 它的文件把上下文長度定義為「模型在記憶體中能存取的最大 token 數」, 並說明加大上下文會增加執行模型所需的記憶體 (來源: Ollama 文件 Context length). 記憶體的估算方式見 <a href="/lanai-handbook/know/k2-quantization">K2</a> 的 KV cache 一節. Ollama 的預設上下文長度與調整方式見 <a href="/lanai-handbook/build/m1-inference">M1</a> 的 M1.8 節.</p><p>上下文越長, 回應通常越慢. 原因是 Transformer 架構 (目前主流語言模型採用的設計) 的自注意力 (self-attention) 機制, 讓模型讀每個新片段時, 都要回頭和前面的片段對照; 每層運算量隨序列長度的平方增加, 也就是內容長度加倍, 對照的工作量約變成四倍 (來源: Vaswani 等人 2017 年論文 Table 1). 輸入越長, 模型開始輸出第一個字之前要算的就越多. 實際的速度差距依推論引擎, 硬體與快取機制而異, 本章不給單一數字 (推論, 信心: 中). 實務上的做法是: 上下文只開到任務需要的長度, 並用 <a href="/lanai-handbook/build/m6-observability">M6</a> 的耗時紀錄比較前後差異.</p><p>下圖是 token, 上下文長度與記憶體, 速度之間的關係:</p>',8)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-130",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%96%87%E7%AB%A0%22%5D%20--%3E%7C%22%E5%88%87%E6%88%90%E5%B0%8F%E7%89%87%E6%AE%B5%22%7C%20K%5B%22token%22%5D%0A%20%20K%20--%3E%20W%0A%20%20subgraph%20W%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E9%95%B7%E5%BA%A6%3A%20%E4%B8%80%E6%AC%A1%E8%83%BD%E8%99%95%E7%90%86%E7%9A%84%20token%20%E4%B8%8A%E9%99%90%22%5D%0A%20%20%20%20Q%5B%22%E5%95%8F%E9%A1%8C%22%5D%0A%20%20%20%20D%5B%22%E8%B2%BC%E9%80%B2%E5%8E%BB%E7%9A%84%E8%B3%87%E6%96%99%22%5D%0A%20%20%20%20R%5B%22%E6%A8%A1%E5%9E%8B%E5%AF%AB%E5%87%BA%E7%9A%84%E5%9B%9E%E7%AD%94%22%5D%0A%20%20end%0A%20%20W%20--%3E%20M%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E8%B6%8A%E9%95%B7%3Cbr%2F%3E%E9%9C%80%E8%A6%81%E7%9A%84%E8%A8%98%E6%86%B6%E9%AB%94%E8%B6%8A%E5%A4%9A%22%5D%0A%20%20W%20--%3E%20S%5B%22%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%3A%20%E9%95%B7%E5%BA%A6%E5%8A%A0%E5%80%8D%3Cbr%2F%3E%E6%AF%8F%E5%B1%A4%E5%B0%8D%E7%85%A7%E7%9A%84%E5%B7%A5%E4%BD%9C%E9%87%8F%E7%B4%84%204%20%E5%80%8D%22%5D%0A%20%20S%20--%3E%20L%5B%22%E8%BC%B8%E5%85%A5%E8%B6%8A%E9%95%B7%3Cbr%2F%3E%E9%96%8B%E5%A7%8B%E8%BC%B8%E5%87%BA%E5%89%8D%E8%A6%81%E7%AE%97%E7%9A%84%E8%B6%8A%E5%A4%9A%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[11]||(E[11]=A('<p><strong>在架構圖上的位置</strong>: 推論伺服器 (vLLM, Ollama 或 llama.cpp) 的上下文設定, 也就是 VM 推論區的 GPU 記憶體用量.</p><h2 id="k1-3-tokenizer-與嵌入矩陣-文字如何變成數字" tabindex="-1">K1.3 Tokenizer 與嵌入矩陣: 文字如何變成數字 <a class="header-anchor" href="#k1-3-tokenizer-與嵌入矩陣-文字如何變成數字" aria-label="Permalink to &quot;K1.3 Tokenizer 與嵌入矩陣: 文字如何變成數字&quot;">​</a></h2><p>電腦只會算數字, 所以文字進到模型前, 要先經過兩道轉換. 第一道由 Tokenizer 負責: 它像一本切詞規則加編號表, 把句子切成 token, 再為每個 token 找出編號. 第二道由模型內部的嵌入矩陣負責: 它把每個編號換成一串數字, 這串數字可以想成這個片段在一張「意思地圖」上的座標, 意思相近的片段, 座標也靠得近. 模型之後的所有運算, 都在這些座標上進行.</p><p>Tokenizer 是把文字切成 token, 再對應成編號的規則. 它不在權重裡, 而是和權重一起發布的另一份設定. Hugging Face 是發布與下載開放模型的平台, 它維護的 Tokenizers 程式庫專門處理切 token; 該程式庫的範例中, 同一段文字編碼後會得到兩組結果: <code>tokens</code> 是切分後的片段, <code>ids</code> 是每個片段在詞彙表中的編號 (來源: Hugging Face Tokenizers 文件 Quicktour).</p><p>Tokenizer 的存放方式依檔案格式 (模型檔的包裝方式) 不同:</p><table tabindex="0"><thead><tr><th>格式</th><th>Tokenizer 放在哪裡</th><th>來源</th></tr></thead><tbody><tr><td>Hugging Face 格式 (safetensors)</td><td>獨立檔案, 常見為 <code>tokenizer.json</code> 與 <code>tokenizer_config.json</code>, 和 <code>model-*.safetensors</code> 權重檔放在同一個模型庫</td><td>Hugging Face 模型庫檔案列表 (以 openai/gpt-oss-20b 為例)</td></tr><tr><td>GGUF</td><td>和權重包在同一個檔案, 以 <code>tokenizer.ggml.model</code>, <code>tokenizer.ggml.tokens</code> 等中介資料存放; 對話範本也在檔內 (<code>tokenizer.chat_template</code>)</td><td>GGUF 規格文件</td></tr></tbody></table><p>兩者的差別在於: safetensors 是「權重和 Tokenizer 分開放的資料夾」, GGUF 是「全部包成一個檔案」. 常見的 Ollama 與 llama.cpp 使用 GGUF 格式 (推論, 信心: 中; 各引擎支援的格式見 <a href="/lanai-handbook/build/m1-inference">M1</a>).</p><p>下圖比較兩種格式存放 Tokenizer 的方式:</p>',8)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-191",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20S%5B%22Hugging%20Face%20%E6%A0%BC%E5%BC%8F%3A%20%E5%88%86%E9%96%8B%E6%94%BE%E7%9A%84%E8%B3%87%E6%96%99%E5%A4%BE%22%5D%0A%20%20%20%20S1%5B%22model-*.safetensors%3Cbr%2F%3E%E6%AC%8A%E9%87%8D%22%5D%0A%20%20%20%20S2%5B%22tokenizer.json%3Cbr%2F%3Etokenizer_config.json%22%5D%0A%20%20end%0A%20%20subgraph%20G%5B%22GGUF%3A%20%E5%85%A8%E9%83%A8%E5%8C%85%E6%88%90%E4%B8%80%E5%80%8B%E6%AA%94%E6%A1%88%22%5D%0A%20%20%20%20G1%5B%22%E6%AC%8A%E9%87%8D%20(%E5%BC%B5%E9%87%8F)%22%5D%0A%20%20%20%20G2%5B%22Tokenizer%20%E4%B8%AD%E7%B9%BC%E8%B3%87%E6%96%99%3Cbr%2F%3E%E5%B0%8D%E8%A9%B1%E7%AF%84%E6%9C%AC%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...E[2]||(E[2]=[t(" Loading... ",-1)])]),_:1})),E[12]||(E[12]=l("p",null,[t("Tokenizer 必須和權重相符. Transformers (Hugging Face 用來載入與執行模型的 Python 程式庫) 的文件提到, 類別設定不相符時會產生錯誤的 token 編號 (來源: Transformers 文件 Tokenizers). 對話範本 (chat template) 是規定「使用者說的話」和「模型說的話」各用什麼標記包起來的固定格式, 也存放在 Tokenizer 設定中; vLLM 要求模型的 Tokenizer 設定內含對話範本, 否則對話請求會失敗, 須以 "),l("code",null,"--chat-template"),t(" 另外指定 (來源: vLLM 文件 Online serving). 因此, 自行轉檔或量化的模型, 要確認 Tokenizer 與對話範本隨權重一起正確轉出.")],-1)),E[13]||(E[13]=l("p",null,"token 編號之後, 模型以嵌入矩陣 (embedding matrix) 把每個編號對應成一個向量, 也就是一串固定長度的數字. 這個矩陣是權重的一部分, 由訓練學出來: Transformer 原始論文以「學習而得的嵌入」把輸入與輸出 token 轉成固定維度的向量 (來源: Vaswani 等人 2017 年論文第 3.4 節). 模型各層的運算都以這些向量為輸入, 最後再換回 token 編號, 由 Tokenizer 還原成文字.",-1)),E[14]||(E[14]=l("p",null,"下圖是模型產生一次回答的完整流程:",-1)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-201",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%96%87%E5%AD%97%22%5D%20--%3E%20B%5B%22Tokenizer%20%E5%88%87%E5%88%86%22%5D%0A%20%20B%20--%3E%20C%5B%22token%20%E7%B7%A8%E8%99%9F%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%B5%8C%E5%85%A5%E7%9F%A9%E9%99%A3%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%90%91%E9%87%8F%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%A8%A1%E5%9E%8B%E5%90%84%E5%B1%A4%E9%81%8B%E7%AE%97%22%5D%0A%20%20F%20--%3E%20G%5B%22%E4%B8%8B%E4%B8%80%E5%80%8B%20token%20%E7%9A%84%E6%A9%9F%E7%8E%87%22%5D%0A%20%20G%20--%3E%20H%5B%22%E9%81%B8%E5%87%BA%20token%20%E7%B7%A8%E8%99%9F%22%5D%0A%20%20H%20--%3E%7C%22%E6%8E%A5%E5%9C%A8%E5%BA%8F%E5%88%97%E5%BE%8C%E9%9D%A2%2C%20%E9%87%8D%E8%A4%87%E5%88%B0%E5%9B%9E%E7%AD%94%E5%AF%AB%E5%AE%8C%22%7C%20D%0A%20%20H%20--%3E%20I%5B%22Tokenizer%20%E9%82%84%E5%8E%9F%E6%88%90%E6%96%87%E5%AD%97%22%5D%0A"})]),fallback:e(()=>[...E[3]||(E[3]=[t(" Loading... ",-1)])]),_:1})),E[15]||(E[15]=A('<p>上圖的意思是: 模型每次只決定「下一個片段」, 選好之後把它接在後面, 再重複同樣的步驟, 直到回答寫完. 看起來是一整段話, 其實是一個片段一個片段接出來的.</p><p>Tokenizer 通常不必直接操作; 推論伺服器會自動處理. 需要留意的情況只有兩種: 自行轉檔或量化模型, 以及更換對話範本 (見 <a href="/lanai-handbook/build/m1-inference">M1.10 節</a>).</p><p><strong>在架構圖上的位置</strong>: 推論伺服器內部的處理步驟; 模型存放區裡和權重一起入庫的 Tokenizer 檔案.</p><h2 id="k1-4-推論伺服器-把模型開機-並提供讓其他程式呼叫的窗口" tabindex="-1">K1.4 推論伺服器: 把模型開機, 並提供讓其他程式呼叫的窗口 <a class="header-anchor" href="#k1-4-推論伺服器-把模型開機-並提供讓其他程式呼叫的窗口" aria-label="Permalink to &quot;K1.4 推論伺服器: 把模型開機, 並提供讓其他程式呼叫的窗口&quot;">​</a></h2><p>模型檔本身只是放在硬碟裡的大檔案, 不會自己回答問題. 推論伺服器就是把模型「開機」的程式: 它把模型載入記憶體, 開一個服務窗口, 其他程式 (例如聊天介面) 把問題送過來, 它算好答案再送回去. 可以想成餐廳的廚房和出餐口: 模型是廚師的功夫, 推論伺服器是整間廚房, API 是大家約定好的點餐單格式. 三個常用的推論引擎都能接受同一種點餐單 (OpenAI 相容 API), 所以日後換廚房, 前面的聊天介面與自動化工具不用重做.</p><p>推論伺服器 (inference server) 是讓其他程式能呼叫模型的服務, 工作有四件:</p><ol><li>從磁碟載入權重到 GPU 或 CPU 記憶體.</li><li>收到請求時執行 Tokenizer, 套用對話範本.</li><li>計算輸出, 逐一產生 token.</li><li>以 HTTP API 回傳結果; 三個常見引擎都提供 OpenAI 相容 API (也就是沿用 OpenAI 公司訂出的請求格式), 因此介面, 閘道與自動化工具可以用同一種方式呼叫.</li></ol><p>下圖是推論伺服器處理請求的四件工作:</p>',8)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-245",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%A3%81%E7%A2%9F%E4%B8%8A%E7%9A%84%E6%A8%A1%E5%9E%8B%E6%AA%94%22%5D%20--%3E%7C%221.%20%E8%BC%89%E5%85%A5%E6%AC%8A%E9%87%8D%E5%88%B0%20GPU%20%E6%88%96%20CPU%20%E8%A8%98%E6%86%B6%E9%AB%94%22%7C%20S%0A%20%20U%5B%22%E8%81%8A%E5%A4%A9%E4%BB%8B%E9%9D%A2%2C%20%E9%96%98%E9%81%93%2C%20%E8%87%AA%E5%8B%95%E5%8C%96%E5%B7%A5%E5%85%B7%22%5D%20--%3E%7C%22%E9%80%81%E5%87%BA%E8%AB%8B%E6%B1%82%20(OpenAI%20%E7%9B%B8%E5%AE%B9%20API)%22%7C%20S%0A%20%20subgraph%20S%5B%22%E6%8E%A8%E8%AB%96%E4%BC%BA%E6%9C%8D%E5%99%A8%3A%20Ollama%2C%20llama.cpp%20%E6%88%96%20vLLM%22%5D%0A%20%20%20%20T%5B%222.%20%E5%9F%B7%E8%A1%8C%20Tokenizer%3Cbr%2F%3E%E5%A5%97%E7%94%A8%E5%B0%8D%E8%A9%B1%E7%AF%84%E6%9C%AC%22%5D%0A%20%20%20%20C%5B%223.%20%E8%A8%88%E7%AE%97%E8%BC%B8%E5%87%BA%3Cbr%2F%3E%E9%80%90%E4%B8%80%E7%94%A2%E7%94%9F%20token%22%5D%0A%20%20%20%20T%20--%3E%20C%0A%20%20end%0A%20%20S%20--%3E%7C%224.%20%E4%BB%A5%20HTTP%20API%20%E5%9B%9E%E5%82%B3%E7%B5%90%E6%9E%9C%22%7C%20U%0A"})]),fallback:e(()=>[...E[4]||(E[4]=[t(" Loading... ",-1)])]),_:1})),E[16]||(E[16]=A('<p>三個引擎的定位不同:</p><table tabindex="0"><thead><tr><th>引擎</th><th>定位</th><th>官方自述的重點</th><th>本手冊建議的用途</th></tr></thead><tbody><tr><td>Ollama</td><td>安裝最簡單, 適合先試用</td><td>支援 OpenAI API 的子集, 包含 <code>/v1/chat/completions</code> 與 <code>/v1/embeddings</code>, 本機預設位址 <code>http://localhost:11434/v1/</code> (Ollama 文件 OpenAI compatibility)</td><td>個人, 最快開始</td></tr><tr><td>llama.cpp (llama-server)</td><td>輕量, 參數可以細調, 低階硬體也能跑</td><td>以 C/C++ 撰寫的輕量 HTTP 伺服器, 在 GPU 與 CPU 執行 F16 與量化模型, 提供 OpenAI 相容的 chat completions, responses 與 embeddings 路徑, 支援多使用者平行解碼與 continuous batching (llama.cpp server README)</td><td>個人或低階硬體, 想精細控制參數</td></tr><tr><td>vLLM</td><td>為多人同時使用設計, 單位時間能服務的量大</td><td>以 PagedAttention 管理注意力運算的記憶體, 持續批次處理請求, 官方標榜高吞吐量 (單位時間處理的請求量); 支援 NVIDIA, AMD GPU 與多種 CPU (vLLM 文件首頁)</td><td>企業或多人並行</td></tr></tbody></table><p>「定位」與「本手冊建議的用途」兩欄依架構決定整理 (信心: 中, 屬整理者判斷). 安裝與加固步驟見 <a href="/lanai-handbook/build/m1-inference">M1</a>.</p><p><strong>在架構圖上的位置</strong>: VM 推論區的 vLLM (個人或低階硬體用 Ollama 或 llama.cpp), 只接受閘道區連線.</p><h2 id="k1-5-嵌入模型與向量-「問自己的文件」需要另一個模型" tabindex="-1">K1.5 嵌入模型與向量: 「問自己的文件」需要另一個模型 <a class="header-anchor" href="#k1-5-嵌入模型與向量-「問自己的文件」需要另一個模型" aria-label="Permalink to &quot;K1.5 嵌入模型與向量: 「問自己的文件」需要另一個模型&quot;">​</a></h2><p>對話模型沒讀過自己的文件, 直接問它公司內部規章, 它答不出來. 解法像開書考試: 先用「依意思找資料」的方式, 從文件裡翻出最相關的幾段, 再把這幾段和問題一起交給對話模型, 請它依這幾段回答. 這個做法稱為檢索增強生成 (RAG). 「依意思找資料」靠的是另一個專門的小模型, 稱為嵌入模型: 它把每一段文字換成一串數字 (向量), 意思相近的段落, 數字也相近, 所以拿問題的數字去比對, 就能找出可能含有答案的段落.</p><p>嵌入模型的輸出不是文字, 而是向量. Ollama 文件說明, 嵌入會把文字轉成數值向量, 可存入向量資料庫 (專門存放並快速比對向量的資料庫), 用於語意搜尋與檢索; 向量長度依模型而定, 常見為 384 至 1,024 維 (維是向量裡數字的個數), 並建議以餘弦相似度 (cosine similarity, 一種比較兩串數字方向是否接近的算法) 比較 (來源: Ollama 文件 Embeddings). 意思相近的兩段文字, 向量也會相近, 因此用問題的向量去找最接近的段落向量, 就能找出可能含有答案的段落.</p><p>下圖是建庫與提問兩條流程:</p>',8)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-329",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20B%5B%22%E5%BB%BA%E5%BA%AB%3A%20%E4%BA%8B%E5%89%8D%E5%81%9A%E4%B8%80%E6%AC%A1%2C%20%E6%96%87%E4%BB%B6%E6%9B%B4%E6%96%B0%E6%99%82%E5%86%8D%E8%A3%9C%22%5D%0A%20%20%20%20B1%5B%22%E6%96%87%E4%BB%B6%22%5D%20--%3E%20B2%5B%22%E5%88%87%E6%AE%B5%22%5D%20--%3E%20B3%5B%22%E5%B5%8C%E5%85%A5%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20B4%5B%22%E5%90%91%E9%87%8F%22%5D%20--%3E%20B5%5B(%22%E5%90%91%E9%87%8F%E5%BA%AB%20(Qdrant)%22)%5D%0A%20%20end%0A%20%20subgraph%20Q%5B%22%E6%8F%90%E5%95%8F%3A%20%E6%AF%8F%E6%AC%A1%E6%9C%89%E4%BA%BA%E7%99%BC%E5%95%8F%E6%99%82%22%5D%0A%20%20%20%20Q1%5B%22%E5%95%8F%E9%A1%8C%22%5D%20--%3E%20Q2%5B%22%E5%90%8C%E4%B8%80%E5%80%8B%E5%B5%8C%E5%85%A5%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20Q3%5B%22%E5%90%91%E9%87%8F%22%5D%20--%3E%20Q4%5B%22%E5%90%91%E9%87%8F%E5%BA%AB%E6%89%BE%E5%87%BA%E7%9B%B8%E8%BF%91%E6%AE%B5%E8%90%BD%22%5D%0A%20%20%20%20Q4%20--%3E%20Q5%5B%22%E6%AE%B5%E8%90%BD%E8%88%87%E5%95%8F%E9%A1%8C%E4%B8%80%E8%B5%B7%3Cbr%2F%3E%E4%BA%A4%E7%B5%A6%E5%B0%8D%E8%A9%B1%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20Q6%5B%22%E9%99%84%E5%87%BA%E8%99%95%E7%9A%84%E5%9B%9E%E7%AD%94%22%5D%0A%20%20end%0A%20%20B5%20-.-%3E%20Q4%0A"})]),fallback:e(()=>[...E[5]||(E[5]=[t(" Loading... ",-1)])]),_:1})),E[17]||(E[17]=A('<p>上圖分兩段: 「建庫」是事前把文件整理好存進去, 只需做一次 (文件更新時再補); 「提問」是每次有人發問時發生的事.</p><p>兩點限制要先知道:</p><ul><li><strong>建庫與查詢必須用同一個嵌入模型</strong> (來源: Ollama 文件 Embeddings). 不同模型畫的「意思地圖」不同, 換了模型, 舊的座標就對不上, 所以更換嵌入模型就要重建整個向量庫, 見 <a href="/lanai-handbook/build/m4-retrieval">M4</a>.</li><li><strong>嵌入模型通常比對話模型小很多</strong>, 可以和對話模型放在同一台推論伺服器 (推論, 信心: 中; 大小比較見 M4.2 節).</li></ul><p><strong>在架構圖上的位置</strong>: 推論區的嵌入模型, 入口區的 Docling (文件解析) 與 Qdrant (向量庫), 組裝見 <a href="/lanai-handbook/build/m4-retrieval">M4</a>.</p><h2 id="k1-6-推論-微調與預訓練-用現成的-補習-還是從頭教起" tabindex="-1">K1.6 推論, 微調與預訓練: 用現成的, 補習, 還是從頭教起 <a class="header-anchor" href="#k1-6-推論-微調與預訓練-用現成的-補習-還是從頭教起" aria-label="Permalink to &quot;K1.6 推論, 微調與預訓練: 用現成的, 補習, 還是從頭教起&quot;">​</a></h2><p>三件事都和模型的數字有關, 但難度和花費差很多. 推論是直接使用現成的模型, 像請一位已經受過教育的人幫忙, 數字完全不動. 微調是再用少量資料補習, 讓模型熟悉特定的格式或用語, 數字會跟著調整. 預訓練是從零開始, 用海量文字把一個模型從頭教育出來, 只有少數大型組織做得起. 大多數情況只需要第一種.</p><table tabindex="0"><thead><tr><th>工作</th><th>做什麼</th><th>成本與硬體</th><th>誰需要</th></tr></thead><tbody><tr><td>推論 (inference)</td><td>用既有權重產生回答, 權重不變</td><td>只需放得下權重與上下文的記憶體 (K2)</td><td>幾乎所有讀者</td></tr><tr><td>微調 (fine-tuning)</td><td>以少量資料調整既有模型, 權重會改變</td><td>LoRA (一種只訓練一小部分附加參數的省資源微調做法) 的論文指出, 相較於以 Adam 完整微調 GPT-3 175B, LoRA 可把可訓練參數減少 10,000 倍, GPU 記憶體需求減為三分之一 (Hu 等人 2021 年論文)</td><td>少數讀者, 有固定格式或領域用語需求時</td></tr><tr><td>預訓練 (pretraining)</td><td>從零開始以大量文字訓練出權重</td><td>Meta 公布 Llama 3.1 系列約使用 15 兆 token 的公開資料, 三個尺寸合計約 3,930 萬 H100 GPU 小時 (一張 H100 GPU 運算一小時算 1 GPU 小時), 其中 8B 模型約 146 萬 GPU 小時 (Llama 3.1 模型卡)</td><td>極少數組織</td></tr></tbody></table><p>下圖是三種工作和權重的關係:</p>',8)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-422",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%A0%90%E8%A8%93%E7%B7%B4%3A%20%E5%BE%9E%E9%9B%B6%E4%BB%A5%E5%A4%A7%E9%87%8F%E6%96%87%E5%AD%97%E8%A8%93%E7%B7%B4%3Cbr%2F%3E%E6%A5%B5%E5%B0%91%E6%95%B8%E7%B5%84%E7%B9%94%22%5D%20--%3E%7C%22%E7%94%A2%E7%94%9F%22%7C%20W%5B%22%E6%97%A2%E6%9C%89%E6%AC%8A%E9%87%8D%22%5D%0A%20%20W%20--%3E%7C%22%E6%AC%8A%E9%87%8D%E4%B8%8D%E8%AE%8A%22%7C%20I%5B%22%E6%8E%A8%E8%AB%96%3A%20%E7%94%A8%E6%97%A2%E6%9C%89%E6%AC%8A%E9%87%8D%E7%94%A2%E7%94%9F%E5%9B%9E%E7%AD%94%3Cbr%2F%3E%E5%B9%BE%E4%B9%8E%E6%89%80%E6%9C%89%E8%AE%80%E8%80%85%22%5D%0A%20%20W%20--%3E%7C%22%E4%BB%A5%E5%B0%91%E9%87%8F%E8%B3%87%E6%96%99%E8%AA%BF%E6%95%B4%22%7C%20F%5B%22%E5%BE%AE%E8%AA%BF%3A%20%E6%AC%8A%E9%87%8D%E6%9C%83%E6%94%B9%E8%AE%8A%3Cbr%2F%3E%E5%B0%91%E6%95%B8%E8%AE%80%E8%80%85%22%5D%0A%20%20F%20--%3E%20W2%5B%22%E8%AA%BF%E6%95%B4%E5%BE%8C%E7%9A%84%E6%AC%8A%E9%87%8D%3Cbr%2F%3E%E7%B6%93%20M3%20%E5%85%A5%E5%BA%AB%E6%89%8D%E4%B8%8A%E7%B7%9A%22%5D%0A%20%20W2%20--%3E%20I%0A"})]),fallback:e(()=>[...E[6]||(E[6]=[t(" Loading... ",-1)])]),_:1})),E[18]||(E[18]=A('<p>多數需求用提示 (把需求寫清楚交給模型) 與檢索 (K1.5 節) 即可解決, 仍不足時才考慮微調 (信心: 中). 判斷流程見 <a href="/lanai-handbook/train/t1-decide">T1</a>.</p><p><strong>在架構圖上的位置</strong>: 架構圖只涵蓋推論. 微調與預訓練不在圖上; 微調後的權重仍要經過模型入庫流程 (M3) 才能上線.</p><h2 id="k1-7-權重會記住部分訓練資料-地端模型也一樣" tabindex="-1">K1.7 權重會記住部分訓練資料, 地端模型也一樣 <a class="header-anchor" href="#k1-7-權重會記住部分訓練資料-地端模型也一樣" aria-label="Permalink to &quot;K1.7 權重會記住部分訓練資料, 地端模型也一樣&quot;">​</a></h2><p>模型學習的方式, 有時會把訓練資料裡的某些原文直接記下來, 之後在特定提問下原樣說出. 這件事已在公開的模型上證實過. 下載到自己電腦的模型, 和放在雲端的是同一組數字, 所以「自架就不會有這個問題」是常見的誤解. 自架改變的是輸入的資料交給誰處理, 不是模型知道什麼.</p><p>Carlini 等人 2021 年發表於 USENIX Security (資安學術會議) 的論文, 只靠查詢 GPT-2 就擷取出數百段逐字相同的訓練文字, 內容包含公開的個人識別資訊 (姓名, 電話, 電子郵件), IRC 對話 (一種網路聊天), 程式碼與 128 位元 UUID (一種識別碼); 有些序列在訓練資料中只出現在一份文件裡, 而且較大的模型比較小的模型更容易洩漏 (來源: 該論文摘要).</p><p>這對地端部署有兩個意涵:</p><ul><li><strong>地端模型帶著同樣的知識與記憶</strong>. 下載到本機的權重, 和在雲端執行時是同一組數字. 自架不會讓模型「忘記」訓練資料, 也不會讓它自動知道讀者的內部資料.</li><li><strong>地端與雲端的差別在「在哪裡跑」</strong>. 自架改變的是輸入 (提示, 文件, 對話紀錄) 由誰處理, 存在哪裡, 而不是模型知道什麼 (信心: 高).</li></ul><p>下圖是權重, 執行位置與輸入之間的關係:</p>',8)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-456",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%A8%93%E7%B7%B4%E8%B3%87%E6%96%99%22%5D%20--%3E%7C%22%E8%A8%93%E7%B7%B4%E6%99%82%E5%8F%AF%E8%83%BD%E8%A8%98%E4%B8%8B%E9%83%A8%E5%88%86%E5%8E%9F%E6%96%87%22%7C%20W%5B%22%E6%AC%8A%E9%87%8D%22%5D%0A%20%20W%20--%3E%20L%5B%22%E5%9C%B0%E7%AB%AF%E5%9F%B7%E8%A1%8C%22%5D%0A%20%20W%20--%3E%20C%5B%22%E9%9B%B2%E7%AB%AF%E5%9F%B7%E8%A1%8C%22%5D%0A%20%20L%20--%3E%20X%5B%22%E5%90%8C%E4%B8%80%E7%B5%84%E6%95%B8%E5%AD%97%3Cbr%2F%3E%E5%90%8C%E6%A8%A3%E7%9A%84%E7%9F%A5%E8%AD%98%E8%88%87%E8%A8%98%E6%86%B6%22%5D%0A%20%20C%20--%3E%20X%0A%20%20I%5B%22%E8%BC%B8%E5%85%A5%3A%20%E6%8F%90%E7%A4%BA%2C%20%E6%96%87%E4%BB%B6%2C%20%E5%B0%8D%E8%A9%B1%E7%B4%80%E9%8C%84%22%5D%20--%3E%7C%22%E5%9C%B0%E7%AB%AF%3A%20%E7%95%99%E5%9C%A8%E8%87%AA%E5%B7%B1%E7%9A%84%E7%92%B0%E5%A2%83%E8%99%95%E7%90%86%22%7C%20L%0A%20%20I%20--%3E%7C%22%E9%9B%B2%E7%AB%AF%3A%20%E4%BA%A4%E7%B5%A6%E6%9C%8D%E5%8B%99%E6%8F%90%E4%BE%9B%E8%80%85%E8%99%95%E7%90%86%22%7C%20C%0A"})]),fallback:e(()=>[...E[7]||(E[7]=[t(" Loading... ",-1)])]),_:1})),E[19]||(E[19]=A('<p>因應方向: 模型輸出若可能含個人資料或第三方內容, 無論地端或雲端都要保留人工檢視; 輸入端的保護則靠存取控制與紀錄保存政策 (見 <a href="/lanai-handbook/know/k6-security">K6</a> 與 <a href="/lanai-handbook/build/m6-observability">M6</a>).</p><p><strong>在架構圖上的位置</strong>: 整張圖的資料流; 稽核區 (Langfuse) 保存的是輸入與輸出紀錄, 不是權重內的知識.</p><h2 id="k1-8-本機與雲端的取捨" tabindex="-1">K1.8 本機與雲端的取捨 <a class="header-anchor" href="#k1-8-本機與雲端的取捨" aria-label="Permalink to &quot;K1.8 本機與雲端的取捨&quot;">​</a></h2><p>地端的好處是資料不必交給外部公司, 代價是硬體, 電費與維護都要自己負責. 雲端剛好相反: 省事, 但資料要送出去, 用得越多付得越多. 沒有哪一邊一定比較好, 要看資料有多敏感, 用量多大, 以及有沒有人能長期照顧系統.</p><p>地端不預設優於雲端. 下表整理四個面向的判斷方向, 屬整理者推論 (信心: 中):</p><table tabindex="0"><thead><tr><th>面向</th><th>地端較有利的情況</th><th>雲端較有利的情況</th></tr></thead><tbody><tr><td>隱私</td><td>內部規範或合約要求輸入資料留在自己的環境內</td><td>資料可交給具備相應合約保證的雲端服務</td></tr><tr><td>成本</td><td>用量長期穩定且高, 能攤提硬體</td><td>用量小或波動大, 按量計費較划算</td></tr><tr><td>品質</td><td>開放權重模型的能力已足以完成自己的任務</td><td>任務需要雲端旗艦模型的能力</td></tr><tr><td>維運負擔</td><td>有人每週檢查安全公告, 備份與升級</td><td>沒有固定維運人員</td></tr></tbody></table><p>品質的差距要用自己的題目實測, 不要只看排行榜 (見 <a href="/lanai-handbook/build/m6-observability">M6</a>). 維運負擔容易低估 (推論, 信心: 中): 自架之後, 安全公告, 版本鎖定與備份都由讀者自己負責 (見 <a href="/lanai-handbook/ops/backup">O1 至 O3</a>). 混合做法也可行: 機敏任務走地端模型, 其餘任務經閘道 (統一接收請求, 再分派給不同模型的窗口) 轉送雲端 API.</p><p>下圖是混合做法的資料流向:</p>',8)),(a(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-539",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BB%8B%E9%9D%A2%E8%88%87%E5%90%84%E7%A8%8B%E5%BC%8F%E7%9A%84%E8%AB%8B%E6%B1%82%22%5D%20--%3E%20G%5B%22%E9%96%98%E9%81%93%20(LiteLLM)%22%5D%0A%20%20G%20--%3E%7C%22%E6%A9%9F%E6%95%8F%E4%BB%BB%E5%8B%99%22%7C%20L%5B%22%E5%9C%B0%E7%AB%AF%E6%8E%A8%E8%AB%96%E5%8D%80%3Cbr%2F%3E%E8%B3%87%E6%96%99%E7%95%99%E5%9C%A8%E8%87%AA%E5%B7%B1%E7%9A%84%E7%92%B0%E5%A2%83%22%5D%0A%20%20G%20--%3E%7C%22%E5%85%B6%E9%A4%98%E4%BB%BB%E5%8B%99%22%7C%20C%5B%22%E9%9B%B2%E7%AB%AF%20API%3Cbr%2F%3E%E6%8C%89%E9%87%8F%E8%A8%88%E8%B2%BB%22%5D%0A"})]),fallback:e(()=>[...E[8]||(E[8]=[t(" Loading... ",-1)])]),_:1})),E[20]||(E[20]=A('<p>完整判斷見<a href="/lanai-handbook/decide/summary">一頁決策摘要</a>, <a href="/lanai-handbook/decide/should-self-host">決策樹</a>與<a href="/lanai-handbook/decide/tco">成本試算表</a>.</p><p><strong>在架構圖上的位置</strong>: 閘道區的 LiteLLM 是模型閘道: 各程式的請求先送到這裡, 再轉給地端推論區或雲端 API, 因此是混合做法的切換點 (見 <a href="/lanai-handbook/build/m5-gateway-identity">M5</a>).</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://huggingface.co/docs/tokenizers/quicktour" target="_blank" rel="noreferrer">Hugging Face Tokenizers 文件: Quicktour</a></li><li><a href="https://huggingface.co/docs/transformers/main/en/fast_tokenizers" target="_blank" rel="noreferrer">Hugging Face Transformers 文件: Tokenizers (fast tokenizers)</a></li><li><a href="https://huggingface.co/docs/transformers/main/en/gguf" target="_blank" rel="noreferrer">Hugging Face Transformers 文件: GGUF</a></li><li><a href="https://huggingface.co/openai/gpt-oss-20b/tree/main" target="_blank" rel="noreferrer">Hugging Face 模型庫檔案列表: openai/gpt-oss-20b</a></li><li><a href="https://github.com/ggml-org/ggml/blob/master/docs/gguf.md" target="_blank" rel="noreferrer">GGUF 規格文件 (ggml-org/ggml)</a></li><li><a href="https://arxiv.org/html/1706.03762v7" target="_blank" rel="noreferrer">Vaswani 等人 (2017), Attention Is All You Need</a></li><li><a href="https://docs.ollama.com/context-length" target="_blank" rel="noreferrer">Ollama 文件: Context length</a></li><li><a href="https://docs.ollama.com/api/openai-compatibility" target="_blank" rel="noreferrer">Ollama 文件: OpenAI compatibility</a></li><li><a href="https://docs.ollama.com/capabilities/embeddings" target="_blank" rel="noreferrer">Ollama 文件: Embeddings</a></li><li><a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md" target="_blank" rel="noreferrer">llama.cpp server README</a></li><li><a href="https://docs.vllm.ai/en/latest/" target="_blank" rel="noreferrer">vLLM 文件首頁</a></li><li><a href="https://docs.vllm.ai/en/latest/serving/online_serving/" target="_blank" rel="noreferrer">vLLM 文件: Online serving</a></li><li><a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">Hu 等人 (2021), LoRA: Low-Rank Adaptation of Large Language Models</a></li><li><a href="https://github.com/meta-llama/llama-models/blob/main/models/llama3_1/MODEL_CARD.md" target="_blank" rel="noreferrer">Llama 3.1 模型卡 (meta-llama/llama-models)</a></li><li><a href="https://www.usenix.org/conference/usenixsecurity21/presentation/carlini-extracting" target="_blank" rel="noreferrer">Carlini 等人 (2021), Extracting Training Data from Large Language Models, USENIX Security 2021</a></li><li><a href="https://arxiv.org/abs/2012.07805" target="_blank" rel="noreferrer">同上論文 arXiv 版</a></li><li>文中的類比 (調音台, 餐廳廚房, 開書考試, 意思地圖等): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>',4))])}const u=i(p,[["render",h]]);export{f as __pageData,u as default};
